  const vistos = {}, out = [];
  for (const r of (Array.isArray(resv) ? resv : [])) {
    if (!r || !(agora - r.ts <= RESV_MS)) continue;
    if (live['Ligada' + r.idx] === true || live['CbLigar' + r.idx] === true) continue;
    if (r.idx === ignora || vistos[r.idx]) continue;
    vistos[r.idx] = 1; out.push(r);
