        if (recusar) {
          if (limitaLog('recS', 2000)) { grava('LIMITE', dado, 'LIMITE_EXCEDIDO (C2: RECUSADO na saida da fila, nao foi enviado ao PLC)'); node.warn('capacidade (C2): RECUSADO na saida da fila, banco 595 - ' + dado); }
          flow.set('chv595_ctx', { rota: msg._rota, reqId: msg._reqId, fase: 'reserva', lerAgora: false, esp: { reserva: 'LIMITE_EXCEDIDO' } });   // para o log de comunicacao do 'responde'
          msg.statusCode = 409; msg.headers = { 'Content-Type': 'application/json' };
          msg.payload = { ok: false, codigo: 'LIMITE_EXCEDIDO', erro: 'comando recusado: ' + dado, totalKw: total, limiteKw: lim, origemKw100: origem };
          return [null, msg];
        }
        if (limitaLog('excS', 10000)) { grava('LIMITE', dado, 'LIMITE_EXCEDIDO (so registra; o comando NAO foi recusado)'); node.warn('capacidade (C2): LIMITE_EXCEDIDO banco 595 (so registra) - ' + dado); }
      }
      if (recusar) {
        for (const i of novas) vivas.push({ idx: i, kw: kwChave(live, cfgB, i), ts: agora });          // reserva ate o PLC mostrar a chave ligada
        flow.set('chv595_resv', vivas);
        global.set('bt2_kw_595', { ts: agora, kw: Math.round((kwCom([]) + somaResv(vivas)) * 1000) / 1000 });   // os outros bancos enxergam a reserva na hora
      }
    }
  }
} catch (e) { node.warn('capacidade (C2 reserva): erro ao avaliar (o comando segue normalmente): ' + e.message); }
return [msg, null];

