if (!p || typeof p !== 'object') return ruim('sem dados');
const out = Object.assign({}, p);
for (const b of BLOCOS) {
  const v = p[b.nome];
  if (!Array.isArray(v) || v.length < b.tam || v.slice(0, b.tam).some(x => typeof x !== 'number' || !isFinite(x))) return ruim(b.nome);
