// PORTAO 3 (D3) - "Nunca confie no cliente": rota de ESCRITA so aceita pedido que veio da PROPRIA tela e em JSON.
// CORS sozinho NAO protege (o browser envia o POST mesmo assim); por isso o servidor confere Origin/Referer e Content-Type.
// Origem permitida = mesmo host da pagina (cabecalho Host) ou item de BT2_ORIGENS_OK (variavel da ABA, ex.: http://servidor:1880,null).
const h = (msg.req && msg.req.headers) || {};
const host = String(h.host || '').toLowerCase();
const extras = String(env.get('BT2_ORIGENS_OK') || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const hostDe = u => { try { return new URL(String(u)).host.toLowerCase(); } catch (e) { return null; } };
const origemDe = u => { try { return new URL(String(u)).origin.toLowerCase(); } catch (e) { return null; } };
let motivo = null;
if (h.origin !== undefined) {
  const o = String(h.origin).toLowerCase();
  if (!((host && hostDe(o) === host) || extras.includes(o))) motivo = 'origem_nao_permitida';
} else if (h.referer !== undefined) {
  const r = origemDe(h.referer);
  if (!((host && hostDe(h.referer) === host) || (r && extras.includes(r)))) motivo = 'origem_nao_permitida';
} else {
  motivo = 'sem_origem';
}
if (!motivo && !/^application\/json\s*(;|$)/i.test(String(h['content-type'] || ''))) motivo = 'content_type_invalido';
if (motivo) {
  node.warn('D3 bloqueado: ' + motivo + ' | ' + String((msg.req && msg.req.method) || '') + ' ' + String((msg.req && msg.req.url) || '').slice(0, 80) + ' | origin=' + String(h.origin || h.referer || '-').slice(0, 80));
  msg.statusCode = 403;
  msg.payload = { ok: false, codigo: 'D3_' + motivo, erro: 'pedido recusado: so e aceito da propria tela do medidor, em JSON (' + motivo + ')' };
  return [null, msg];
}
return [msg, null];

// FASE 4 (P3-E1): comando que NAO e de seguranca e recusado NA ENTRADA com leitura velha (> 2,5 s), em vez de esperar o vigia de 8 s na fila.
// Desligar chave, desligar banco e desselecionar passam sempre (seguranca).
const b = msg.payload || {};
const rota = "valida ligar";
const seguranca = !(Array.isArray(b.ligar) && b.ligar.length > 0);   // lote so de DESLIGAR passa sempre (seguranca)
if (seguranca) return [msg, null];
const ts = flow.get('chv595_live_ts') || 0;
if (ts && Date.now() - ts <= 2500) return [msg, null];
if (!ts) return [msg, null];   // sem 1a leitura: a propria valida ja responde 'aguardando a 1a leitura'
msg.statusCode = 503; msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: false, codigo: 'LEITURA_VELHA', erro: 'sem leitura recente do PLC (ha ' + Math.round((Date.now() - ts) / 1000) + ' s) - comando NAO enviado', idadeMs: Date.now() - ts };
return [null, msg];

// Passo 10 (21/11/2026) - VALIDA LOTE: POST /api/chaves/595/lote  {"ligar":[indices], "desligar":[indices]}. Mesmas regras do "valida ligar" para CADA chave a ligar; desligar e sempre permitido (seguranca).
// Tudo ou nada: se UMA chave a ligar nao puder, o lote inteiro e recusado e nada e escrito. Um lote so com "desligar" passa sempre (como desligar uma chave).
const b = msg.payload || {};
const falha = (t, code) => { msg.statusCode = code || 400; msg.payload = { ok: false, erro: t }; return [null, msg]; };
const N = 18;
const lig = b.ligar === undefined ? [] : b.ligar, des = b.desligar === undefined ? [] : b.desligar;
if (!Array.isArray(lig) || !Array.isArray(des)) return falha('ligar e desligar devem ser listas de indices');
const todos = lig.concat(des);
if (!todos.length) return falha('informe ao menos uma chave em ligar ou desligar');
if (todos.some(i => !Number.isInteger(i) || i < 1 || i > N)) return falha('indices devem ser inteiros de 1 a ' + N);
if (new Set(todos).size !== todos.length) return falha('uma chave nao pode aparecer duas vezes (nem em ligar e em desligar ao mesmo tempo)');
const live = flow.get('chv595_live');
if (!live) return falha('aguardando a 1a leitura do PLC - tente de novo em instantes', 503);
if (lig.length) {                    // desligar e sempre permitido (seguranca)
  if (live.LigarBanco !== true) return falha('banco BC59,5 desligado - acione "Ligar banco" antes (seletora em Auto)', 409);
  for (const i of lig) {
    if (live['Habilitada' + i] !== true) return falha('chave ' + i + ' esta desabilitada (habilite antes de ligar)');
    if (live['Ligada' + i] === true && (live['FalhaRet' + i] === true || live['ContColado' + i] === true)) { msg.statusCode = 409; msg.payload = { ok: false, codigo: 'CONTATOR_COLADO', erro: 'chave ' + i + ': retorno (SB) ativo sem comando - contator colado? verifique no campo antes de ligar' }; return [null, msg]; }
    if (live.ComEt200Ok === true && live['HabResp' + i] !== true) { msg.statusCode = 409; msg.payload = { ok: false, codigo: 'HAB_NAO_CONFIRMADA', erro: 'chave ' + i + ': o PLC do banco ainda nao confirmou a habilitacao - aguarde e tente de novo' }; return [null, msg]; }
  }
  if (live.ComEt200Ok === true && live.RespEcoOk !== true) { msg.statusCode = 409; msg.payload = { ok: false, codigo: 'SEM_ECO', erro: 'o PLC do banco nao confirmou o ultimo pacote (eco) - aguarde e tente de novo' }; return [null, msg]; }
  if (live.ChaveSel) return falha('Setup em andamento (chave ' + live.ChaveSel + ' selecionada) - desmarque no Setup antes de ligar outras', 409);
}
msg.payload = { ligar: lig, desligar: des };
msg._rota = 'LOTE';
return [msg, null];
